static uint32_t bin_to_int(const uint8_t* s, int r) {
    uint32_t val = 0;
    for (int i = 0; i < r; i++)
        val |= (s[i] ? (1U << i) : 0);
    return val;
}

static void int_to_bin(uint32_t v, uint8_t* s, int r) {
    memset(s, 0, r);
    for (int i = 0; i < r; i++)
        s[i] = (v >> i) & 1;
}

